namespace ghidra.app.plugin.core.compositeeditor;



using docking;
using docking.action;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.util.exception;

/**
 * Action for use in the composite data type editor.
 * This action has help associated with it.
 */
public class PointerAction : CompositeEditorTableAction {

	public static string ACTION_NAME = "Create Pointer";
	private static string GROUP_NAME = COMPONENT_ACTION_GROUP;
	private static string DESCRIPTION = "Create a pointer(s) on the selection";
	private static DataType POINTER_DT = new PointerDataType();

	public PointerAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, GROUP_NAME, null, null, null)
    {
		setDescription(DESCRIPTION);
		setKeyBindingData(new KeyBindingData(KeyEvent.VK_P, 0));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}
		try {
			model.add(POINTER_DT);
		}
		catch (UsrException e1) {
			model.setStatus(e1.getMessage());
		}
		requestTableFocus();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		// Do nothing since we always want it enabled so the user gets a "doesn't fit" message.
		return !hasIncompleteFieldEntry() && model.getRowCount() > 0 && model.hasSelection() &&
			model.isContiguousSelection();
	}

}
